    [InlineData("Andres Martinez sacó 2.6 en Cálculo")]
    [Trait("CA", "CA-21")]
    [Trait("ESC", "ESC-193")]
    [Trait("D", "D-98")]
    public async Task ESC_193_El_verificador_de_personas_bloquea_a_un_tercero_aunque_la_poda_no_exista(string texto)
