    }

    [Fact]
    [Trait("CA", "CA-21")]
    [Trait("ESC", "ESC-199")]
    [Trait("D", "D-98")]
    public async Task ESC_199_g_Los_motivos_de_reintento_de_f_y_g_se_calculan_sobre_el_texto()
