        Func<SolicitudLlm, int, RespuestaLlm> guion,
        IBaseConocimiento? baseConocimiento = null,
        string? canario = null,
        DatosAcademicos? datos = null) =>
        new(guion, baseConocimiento ?? new IndiceRelevante(), canario, datos ?? DatosReferencia.Cargar());

