    private static string ContenidoDeHerramienta(LlmDoble llm, int indice)
    {
        var mensaje = llm.Solicitudes[indice].Mensajes.First(m => m.Rol == RolMensaje.Herramienta).Contenido;
        var lineas = Lineas(mensaje);
