using TutorFlow.Core.Asistente;
using TutorFlow.Core.Autorizacion;
using TutorFlow.Core.Conocimiento;
using static TutorFlow.Core.Tests.Asistente.EscenarioAsistente;
using static TutorFlow.Core.Tests.Asistente.SalidasVerificadas;
using static TutorFlow.Core.Tests.Asistente.SeccionesDeReferencia;

namespace TutorFlow.Core.Tests.Asistente;

public sealed class DefinitivaSoloConLecturaDelProgramaTests
{
    private const string PreguntaDefinitiva = "¿Qué dice el reglamento sobre la habilitación?";
    private static readonly Cita DatosProgramaAdm = new(Textos.DocumentoDatosPrograma, "ADM");
    private static readonly Usuario Coord02 = new(Rol.Coordinador, "COORD-02");

    private static EscenarioAsistente ConSoloElPrograma(string texto) =>
        Con(
            (_, llamada) => llamada == 0 ? Herramienta(HerramientasAsistente.Programa) : Texto(texto),
            Indice(Articulo5, Articulo6, Articulo20));

    [Fact]
    [Trait("CA", "CA-06")]
    [Trait("ESC", "ESC-179")]
    [Trait("SEG", "SEG-10g")]
    public async Task ESC_179k_La_definitiva_que_no_esta_en_el_resultado_del_programa_da_numero_no_verificado()
    {
        var escenario = ConSoloElPrograma("La definitiva de Valentina Castro en Estadística es 3.2.");

        var resultado = await escenario.PreguntarAsync(Coord02, PreguntaDefinitiva);

        var respuesta = resultado.Respuesta!;
        Assert.Equal(Textos.NoVerificable, respuesta.Respuesta);
        Assert.Empty(respuesta.Citas);
        Assert.True(respuesta.UsoDatosEstudiante);
        Assert.Equal(ResultadoAuditoria.NumeroNoVerificado, resultado.Auditoria);
        Assert.Equal(ResultadoAuditoria.NumeroNoVerificado, Assert.Single(escenario.Auditoria.Eventos).Resultado);
    }

    [Fact]
    [Trait("CA", "CA-06")]
    [Trait("ESC", "ESC-179")]
    [Trait("SEG", "SEG-10g")]
    public async Task ESC_179l_La_definitiva_que_lista_el_resultado_del_programa_se_entrega_con_la_cita_del_programa()
    {
        const string texto = "La definitiva de Valentina Castro en Estadística es 2.3.";
        var escenario = ConSoloElPrograma(texto);

        var resultado = await escenario.PreguntarAsync(Coord02, PreguntaDefinitiva);

        AfirmarRespondida(resultado, escenario, texto);
        Assert.Contains(DatosProgramaAdm, resultado.Respuesta!.Citas);
    }

    [Fact]
    [Trait("CA", "CA-06")]
    [Trait("ESC", "ESC-179")]
    [Trait("SEG", "SEG-10g")]
    public async Task ESC_179_El_resultado_de_la_herramienta_de_programa_lista_las_perdidas_de_la_estudiante_con_su_definitiva()
    {
        var escenario = ConSoloElPrograma("La definitiva de Valentina Castro en Estadística es 2.3.");

        await escenario.PreguntarAsync(Coord02, PreguntaDefinitiva);

        var resultadoDeLaHerramienta = escenario.Llm.TextoDeLlamada(1);
        Assert.Contains("Estudiante: Valentina Castro (ID EST-005)", resultadoDeLaHerramienta, StringComparison.Ordinal);
        Assert.Contains("Perdida por nota: Microeconomía (definitiva 1.8)", resultadoDeLaHerramienta, StringComparison.Ordinal);
        Assert.Contains("Perdida por nota: Estadística (definitiva 2.3)", resultadoDeLaHerramienta, StringComparison.Ordinal);
        Assert.Contains("Estudiantes con asignaturas perdidas: Valentina Castro (Microeconomía 1.8; Estadística 2.3)", resultadoDeLaHerramienta, StringComparison.Ordinal);
        Assert.DoesNotContain("Contabilidad 3.2", resultadoDeLaHerramienta, StringComparison.Ordinal);
        Assert.DoesNotContain("Contabilidad (definitiva 3.2)", resultadoDeLaHerramienta, StringComparison.Ordinal);
    }
}

    [Fact]
    [Trait("CA", "CA-17")]
    [Trait("CA", "CA-22")]
    [Trait("ESC", "ESC-198")]
    [Trait("D", "D-64")]
    public async Task ESC_198g3_Un_par_con_el_primer_corte_de_la_asignatura_se_entrega_sin_cambios()
    {
        const string texto = "Contabilidad 3.6 en el primer corte.";
        var escenario = Con(LeeLosCortesYResponde(texto), IndiceDeNormas());

        var resultado = await escenario.PreguntarAsync(Est004, "¿Qué dice el reglamento sobre la habilitación?");

        SalidasVerificadas.AfirmarRespondida(resultado, escenario, texto);
    }

    [Fact]
    [Trait("CA", "CA-17")]
    [Trait("CA", "CA-22")]
    [Trait("ESC", "ESC-198")]
    [Trait("D", "D-64")]
    public async Task ESC_198g4_Los_pares_de_Valentina_que_son_sus_definitivas_en_la_prelectura_se_entregan()
    {
        const string texto = "Valentina Castro: Microeconomía (1.8) y Estadística (2.3).";
        var escenario = Con(SalidasVerificadas.LeeElProgramaYResponde(texto), IndiceDeNormas());

        var resultado = await escenario.PreguntarAsync(Coord02, PreguntaPerdidas);

        SalidasVerificadas.AfirmarRespondida(resultado, escenario, texto);
        Assert.Equal(2, escenario.Llm.Solicitudes.Count);
    }

    [Fact]
    [Trait("CA", "CA-17")]
    [Trait("CA", "CA-22")]
    [Trait("ESC", "ESC-198")]
    [Trait("D", "D-64")]
    [Trait("SEG", "SEG-10c")]
    public async Task ESC_198g5_La_definitiva_de_una_aprobada_que_la_prelectura_no_lista_da_numero_no_verificado_antes_que_el_par()
    {
        var escenario = Con(SalidasVerificadas.LeeElProgramaYResponde("Camilo Rojas: Contabilidad 3.9."), IndiceDeNormas());

        var resultado = await escenario.PreguntarAsync(Coord02, PreguntaPerdidas);

        Assert.Equal(Textos.NoVerificable, resultado.Respuesta!.Respuesta);
        Assert.Empty(resultado.Respuesta.Citas);
        Assert.Equal(ResultadoAuditoria.NumeroNoVerificado, resultado.Auditoria);
        Assert.Equal(ResultadoAuditoria.NumeroNoVerificado, Assert.Single(escenario.Auditoria.Eventos).Resultado);
    }

    [Fact]
    [Trait("CA", "CA-17")]
    [Trait("ESC", "ESC-198")]
    [Trait("D", "D-64")]
    public async Task ESC_198g_La_acumulada_de_la_asignatura_sin_definitiva_cuadra_como_par()
    {
        const string texto = "Estadística: 2.4.";
        await ClasesVerificadoras.AfirmarPasaAsync("EST-006", texto, "EST-006");
    }
}

