    {
        var partes = texto.Split(" · ");
        return new Cita(partes[0], partes[1]);
    }

    private static string Limpiar(string respuesta, string[] citas) =>
        ReferenciasEscritas.Limpiar(respuesta, [.. citas.Select(DesdeTexto)]);

